actions.example:
params:
  orders: "{{ results.load.output.rows }}"
  rate: 0.19
script: |
  const sum = params.orders.reduce((s, o) => s + Number(o.amount), 0);
  console.log(`${params.orders.length} orders`);
  return { net: sum, gross: sum * (1 + params.rate) };

transforms.example:
fields:
  - { name: total, value: "{{ record.price * record.quantity }}" }
  - { name: label, value: "{{ upper(record.name) }}: {{ record.total }}" }

fields:
  - { name: source, value: runnel }
  - { name: batch, value: "{{ params.BATCH }}" }

fields:
  - { name: kdnr, type: int }
  - { name: umsatz, type: decimal, format: "#.##0,00" }

groupBy: [Datum]
aggregates:
  - { name: orders, function: count }
  - { name: total, function: sum, field: Betrag }

field: status
as: statusText
values:
  - { from: A, to: Active }
  - { from: I, to: Inactive }
default: Unknown

fields:
  - { name: name, type: string }
  - { name: amount, type: decimal }
script: |
  if (!record.name) return null; // drop the record
  return { name: record.name.trim(), amount: record.amount };

fields:
  - { name: kdnr, as: externalId }
  - { name: name }
# or instead of fields:
# remove: [telefon]

fields:
  - { name: total, descending: true }
  - { name: name, ignoreCase: true }

keys:
  - { field: customerId, lookupField: id }
return:
  - { lookupField: name, as: customerName }

cases:
  - { when: "{{ record.umsatz >= 10000 }}", to: key-accounts }
  - { when: "{{ record.umsatz > 0 }}", to: standard }
default: others

path: data/orders.csv
delimiter: ";"
fields:
  - { name: Nr, type: int }
  - { name: Betrag, type: decimal, format: "#.##0,00" }

path: out/orders.csv
fields:
  - { name: Datum, format: dd.MM.yyyy }
  - { name: Betrag, format: "#.##0,00" }

connection: app-db
table: customers
keys:
  - { field: customerId, column: id }
return:
  - { column: name, as: customerName }

path: data/orders.xlsx
sheet: Orders
range: A3
fields:
  - { name: Nr, type: int }
  - { name: Date, type: date }
  - { name: Amount, type: decimal }

path: out/orders.xlsx
sheet: Orders
fields:
  - { name: Nr }
  - { name: Amount, format: "#.##0,00" }
  - { name: Date, format: dd.MM.yyyy }
  - { name: Share, excelFormat: 0.0% }

path: data/orders.json
records: data.items
fields:
  - { name: id, type: int }
  - { name: city, from: address.city }

path: out/orders.json
fields:
  - { name: id }
  - { name: day, format: dd.MM.yyyy }

path: data/orders.xml
records: orders/order
fields:
  - { name: id, from: "@id", type: int }
  - { name: customer, from: customer/name }
  - { name: amount, type: decimal }

path: out/orders.xml
root: orders
record: order
fields:
  - { name: id, as: "@id" }
  - { name: customer, as: customer/name }
  - { name: amount }
